<?php declare(strict_types=1);$action=(string)($_GET['action']??'');$editId=(string)($_GET['id']??'');$editing=null;$editingRoles=[];$editingProjects=[];if($action==='edit'&&$editId){$q=$db->prepare('SELECT * FROM users WHERE id=? AND company_id=?');$q->execute([$editId,$user['company_id']]);$editing=$q->fetch();if($editing){$q=$db->prepare('SELECT role_id FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=? AND r.company_id=? AND ur.scope_type="company"');$q->execute([$editId,$user['company_id']]);$editingRoles=$q->fetchAll(PDO::FETCH_COLUMN);$q=$db->prepare('SELECT project_id FROM user_projects up JOIN projects p ON p.id=up.project_id WHERE up.user_id=? AND p.company_id=?');$q->execute([$editId,$user['company_id']]);$editingProjects=$q->fetchAll(PDO::FETCH_COLUMN);}}?>
<section class="page-title user-page-title"><div><span class="eyebrow">PEOPLE</span><h1>Users</h1><p class="muted">Add employees and manage each person’s job role and project access from one place.</p></div><a class="button" href="?page=users&action=add">Add user</a></section>
