<?php elseif($editing):?><form class="form-card user-editor" method="post"><div class="editor-head"><div><span class="eyebrow">EDIT USER</span><h2><?=e($editing['name'])?></h2><p class="muted"><?=e($editing['email'])?></p></div><a href="?page=users">Back to users</a></div><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="user_id" value="<?=e($editing['id'])?>"><div class="form-grid"><label class="field">Designation<input name="designation" value="<?=e($editing['designation'])?>"></label><label class="field">Phone<input name="phone" value="<?=e($editing['phone'])?>"></label><label class="field">Account status<select name="user_status"><option value="active" <?=$editing['status']==='active'?'selected':''?>>Active</option><option value="suspended" <?=$editing['status']==='suspended'?'selected':''?>>Suspended</option></select></label></div><div class="access-section"><h3>Job roles</h3><p class="muted">Select one or more roles. Permissions are already organised by responsibility.</p><div class="role-choice-grid"><?php foreach($roles as $role):?><label class="role-choice"><input type="checkbox" name="role_ids[]" value="<?=e($role['id'])?>" <?=in_array($role['id'],$editingRoles,true)?'checked':''?>><span><b><?=e($role['name'])?></b><small><?=e($role['description'])?></small></span></label><?php endforeach;?></div></div><div class="access-section"><h3>Assigned projects</h3><p class="muted">Leave all unchecked for company-level staff, or select the projects this employee works on.</p><div class="project-choice-grid"><?php foreach($projects as $project):?><label><input type="checkbox" name="project_ids[]" value="<?=e($project['id'])?>" <?=in_array($project['id'],$editingProjects,true)?'checked':''?>> <span><b><?=e($project['name'])?></b><small><?=e($project['code'].' · '.$project['location'])?></small></span></label><?php endforeach;?></div></div><button class="button" name="save_user_access" value="1">Save user access</button></form>
<?php else:?><section class="user-list"><?php foreach($users as $item):?><article class="user-row"><div class="user-avatar"><?=e(strtoupper(substr($item['name'],0,1)))?></div><div class="user-identity"><b><?=e($item['name'])?></b><small><?=e($item['email'])?><?=e($item['designation']?' · '.$item['designation']:'')?></small></div><div class="user-access"><small>ROLE</small><span><?=e($item['role_names']?:'No role assigned')?></span></div><div class="user-access"><small>PROJECTS</small><span><?=e($item['project_names']?:'Company level / none selected')?></span></div><span class="pill <?=$item['status']==='active'?'good':'bad'?>"><?=e($item['status'])?></span><a class="edit-user" href="?page=users&action=edit&id=<?=e($item['id'])?>">Edit</a></article><?php endforeach;?></section><?php endif;?>
